def transform(g):
    h,w=len(g),len(g[0])
    # exterior zeros via 8-conn flood from border
    ext=[[False]*w for _ in range(h)]; dq=deque()
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and (i in(0,h-1) or j in(0,w-1)):
                ext[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di in(-1,0,1):
            for dj in(-1,0,1):
                ni,nj=i+di,j+dj
                if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and not ext[ni][nj]:
                    ext[ni][nj]=True; dq.append((ni,nj))
    # 1-components (8-conn)
    seen=[[False]*w for _ in range(h)]; out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==1 and not seen[i][j]:
                comp=[]; dq=deque([(i,j)]); seen[i][j]=True
                while dq:
                    a,b=dq.popleft(); comp.append((a,b))
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            na,nb=a+di,b+dj
                            if 0<=na<h and 0<=nb<w and g[na][nb]==1 and not seen[na][nb]:
                                seen[na][nb]=True; dq.append((na,nb))
                # adjacent zeros
                adjz=set()
                for a,b in comp:
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            na,nb=a+di,b+dj
                            if 0<=na<h and 0<=nb<w and g[na][nb]==0:
