                has_interior=any(not ext[a] for a in adjz.__iter__() for a in [a] ) if False else any(not ext[p[0]][p[1]] for p in adjz)
                if not has_interior: continue
                for a,b in adjz:
                    out[a][b]=2 if ext[a][b] else 3
    return out

